-- Applied to production Supabase after GMP transaction integrity v3.
DROP POLICY IF EXISTS gmp_products_owner_all ON public.gmp_products;
CREATE POLICY gmp_products_member_read ON public.gmp_products FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.gmp_stores s JOIN public.gmp_organization_members m ON m.organization_id=s.organization_id WHERE s.id=gmp_products.store_id AND m.user_id=(select auth.uid())));
CREATE POLICY gmp_products_admin_insert ON public.gmp_products FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.gmp_stores s JOIN public.gmp_organization_members m ON m.organization_id=s.organization_id WHERE s.id=gmp_products.store_id AND m.user_id=(select auth.uid()) AND m.role IN ('owner','admin')));
CREATE POLICY gmp_products_admin_update ON public.gmp_products FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.gmp_stores s JOIN public.gmp_organization_members m ON m.organization_id=s.organization_id WHERE s.id=gmp_products.store_id AND m.user_id=(select auth.uid()) AND m.role IN ('owner','admin'))) WITH CHECK (EXISTS (SELECT 1 FROM public.gmp_stores s JOIN public.gmp_organization_members m ON m.organization_id=s.organization_id WHERE s.id=gmp_products.store_id AND m.user_id=(select auth.uid()) AND m.role IN ('owner','admin')));
CREATE POLICY gmp_products_admin_delete ON public.gmp_products FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.gmp_stores s JOIN public.gmp_organization_members m ON m.organization_id=s.organization_id WHERE s.id=gmp_products.store_id AND m.user_id=(select auth.uid()) AND m.role IN ('owner','admin')));
